import static org.junit.jupiter.api.Assertions.assertEquals;

import org.eclipse.rdf4j.sail.lmdb.LmdbPipelinePlanCacheBenchmarkSupport;
import org.junit.jupiter.api.Test;

class LmdbPipelinePlanCacheBenchmarkTest {

	@Test
	void servingCasesNeverInvokeRequestBoundPlanning() {
		try (LmdbPipelinePlanCacheBenchmarkSupport stable = LmdbPipelinePlanCacheBenchmarkSupport.stable();
				LmdbPipelinePlanCacheBenchmarkSupport refresh = LmdbPipelinePlanCacheBenchmarkSupport
						.refreshInFlight()) {
			assertEquals("USE", stable.hit().getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			assertEquals("USE_AND_REFRESH",
					refresh.hit().getStringMetricPlanned("optimizer.planCacheLookupOutcome"));
			assertEquals(1, stable.requestComputations());
			assertEquals(1, refresh.requestComputations());
			assertEquals(1, refresh.refreshExecutions());
		}
	}
}
